//! Qur themes (handoff section 12a, decisions 8 and 13).
//!
//! Every built-in theme is a TOML file in `themes/`, embedded with
//! `include_str!` and parsed once on first use. A theme controls the whole UI,
//! the code, diffs, the terminal palette and the 6 agent accents.
//! UI code reads colors only through these tokens, never hard-coded values.
//!
//! The TOML files are generated by `tools/gen_themes.py` from the upstream
//! palettes (sources and licenses in `docs/THEME_CREDITS.md`).
//!
//! CONTRACT (M1): the public API below is used by `qur_app`; keep the
//! signatures. Implementation details (TOML schema, parsing) are free.

use std::sync::{Arc, OnceLock};

mod color;
mod schema;

/// Floor of the window opacity slider: 60% to 100% on every theme (owner,
/// decision 38). [`Theme::min_opacity`] still reports each theme's lowest
/// opacity that keeps text at 4.5:1 over a pure white and a pure black
/// desktop, but the slider no longer stops there.
pub const MIN_OPACITY: f32 = 0.6;

/// sRGB color with alpha, `0xRRGGBBAA`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Rgba(pub u32);

impl Rgba {
    pub const fn r(self) -> u8 {
        (self.0 >> 24) as u8
    }
    pub const fn g(self) -> u8 {
        (self.0 >> 16) as u8
    }
    pub const fn b(self) -> u8 {
        (self.0 >> 8) as u8
    }
    pub const fn a(self) -> u8 {
        self.0 as u8
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Appearance {
    Light,
    Dark,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Default)]
pub struct Style {
    pub color: Option<Rgba>,
    pub bold: bool,
    pub italic: bool,
}

