/// One agent accent slot: the base color (dot, cursor, outline) and four
/// heat tints for file rows (1 = touched once ... 4 = most), all readable on
/// this theme's sidebar background.
#[derive(Clone, Copy, Debug)]
pub struct Accent {
    pub base: Rgba,
    pub glow: Rgba,
    pub heat: [Rgba; 4],
}

#[derive(Clone, Debug)]
pub struct Theme {
    pub name: String,
    pub appearance: Appearance,
    /// "Qur", "Popular", "Accessibility" (picker grouping).
    pub group: &'static str,
    pub high_contrast: bool,
    pub ui: UiColors,
    pub editor: EditorColors,
    pub diff: DiffColors,
    pub terminal: TerminalColors,
    pub accents: [Accent; 6],
    /// Attribution shown in About and docs/THEME_CREDITS.md (None for Qur's own).
    pub credit: Option<Credit>,
    /// This theme's own syntax entries, sorted by name.
    syntax: Vec<(String, Style)>,
    /// The fallback Qur theme's entries (empty for Qur Light/Dark themselves).
    fallback_syntax: Arc<Vec<(String, Style)>>,
    min_opacity: f32,
}

#[derive(Clone, Debug)]
pub struct Credit {
    pub author: &'static str,
    pub license: &'static str, // SPDX id
    pub url: &'static str,
}

impl Theme {
    /// Style for a highlight capture name with dotted fallback:
    /// "function.method.call" -> "function.method" -> "function" -> default text.
    /// The theme's own entries win; then the fallback Qur theme's; then the
    /// editor text color.
    pub fn syntax_style(&self, highlight: &str) -> Style {
        for table in [&self.syntax, &*self.fallback_syntax] {
            let mut name = highlight;
            loop {
                if let Ok(i) = table.binary_search_by(|(k, _)| k.as_str().cmp(name)) {
                    let mut style = table[i].1;
                    style.color.get_or_insert(self.editor.text);
                    return style;
                }
                match name.rfind('.') {
                    Some(dot) => name = &name[..dot],
                    None => break,
                }
            }
        }
        Style { color: Some(self.editor.text), bold: false, italic: false }
    }

    /// Lowest window opacity (0.01 steps, never below [`MIN_OPACITY`]) at
    /// which UI and editor text keep 4.5:1 on every translucent surface over
    /// a pure white and a pure black desktop. 1.0 = this theme can't be
    /// translucent without losing readability.
    pub fn min_opacity(&self) -> f32 {
        self.min_opacity
    }

    /// Black or white logo variant for this background (never tinted).
    pub fn logo_is_white(&self) -> bool {
        let bg = self.ui.top_bar_bg;
        contrast_ratio(Rgba(0xffffffff), bg) >= contrast_ratio(Rgba(0x000000ff), bg)
    }

    /// Parse a theme TOML (built-in format). Missing tokens come from Qur
    /// Light or Qur Dark, chosen by the theme's background luminance.
    pub fn from_toml(src: &str) -> Result<Theme, String> {
        let reg = Registry::global();
        let raw: schema::RawTheme = toml_edit::de::from_str(src).map_err(|e| e.to_string())?;
        let bg = raw.ui.window_bg.or(raw.ui.editor_bg).map(|h| h.0);
        let dark = match (bg, raw.appearance.as_deref()) {
            (Some(bg), _) => bg.luminance() < 0.18,
            (None, Some(a)) => a == "dark",
            (None, None) => true,
        };
        let base = if dark { &reg.qur_dark } else { &reg.qur_light };
        build(raw, Some(base))
    }
}

fn build(raw: schema::RawTheme, base: Option<&Arc<Theme>>) -> Result<Theme, String> {
    let b = base.map(|b| &**b);
    let mut missing = Vec::new();
    let ui = raw.ui.resolve(b.map(|b| &b.ui), &mut missing);
    let editor = raw.editor.resolve(b.map(|b| &b.editor), &mut missing);
    let diff = raw.diff.resolve(b.map(|b| &b.diff), &mut missing);
    let terminal = raw.terminal.resolve(b.map(|b| &b.terminal), &mut missing);
    let accents = schema::accents(raw.accents.as_deref(), b.map(|b| &b.accents), ui.sidebar_bg, ui.text, &mut missing);
    let name = raw.name.unwrap_or_else(|| {
        missing.push("name".into());
        String::new()
    });
    if !missing.is_empty() {
        return Err(format!("theme {name:?} is missing {}", missing.join(", ")));
    }
    let appearance = match raw.appearance.as_deref() {
        Some("light") => Appearance::Light,
        Some("dark") => Appearance::Dark,
        Some(other) => return Err(format!("theme {name:?}: appearance must be light or dark, not {other:?}")),
        None if ui.window_bg.luminance() < 0.18 => Appearance::Dark,
        None => Appearance::Light,
    };
    let group: &'static str = match raw.group.as_deref() {
        Some("Qur") => "Qur",
        Some("Accessibility") => "Accessibility",
        _ => "Popular",
    };
    let syntax: Vec<(String, Style)> = raw.syntax.into_iter().map(|(k, v)| (k, v.style())).collect(); // BTreeMap: sorted
    let fallback_syntax = match b {
        Some(b) => {
            let mut v = (*b.fallback_syntax).clone();
            if v.is_empty() {
                v = b.syntax.clone();
            }
            Arc::new(v)
        }
        None => Arc::new(Vec::new()),
    };
    let min_opacity = opacity_floor(&ui, editor.text);
    Ok(Theme {
        min_opacity,
        name,
        appearance,
        group,
        high_contrast: raw.high_contrast.unwrap_or(false),
        ui,
        editor,
        diff,
        terminal,
        accents,
        credit: raw.credit.map(schema::RawCredit::into_credit),
        syntax,
        fallback_syntax,
    })
}

fn opacity_floor(ui: &UiColors, editor_text: Rgba) -> f32 {
    let surfaces = [ui.window_bg, ui.top_bar_bg, ui.sidebar_bg, ui.editor_bg, ui.panel_bg];
    let readable = |op: f32| {
        let a = (op * 255.0).round() as u8;
        [Rgba(0xffffffff), Rgba(0x000000ff)].iter().all(|&desktop| {
            surfaces.iter().all(|&s| {
                let bg = blend(s.with_alpha(a), desktop);
                [ui.text, editor_text].iter().all(|&t| contrast_ratio(blend(t, bg), bg) >= 4.5)
            })
        })
    };
    let steps = 50u32..=100;
    steps.map(|i| i as f32 / 100.0).find(|&op| readable(op)).unwrap_or(1.0)
}

/// What the user picked.
#[derive(Clone, Debug, PartialEq, Eq, Default)]
pub enum ThemeChoice {
    /// Follow macOS: Qur Light in light mode, Qur Dark in dark mode.
    #[default]
    Auto,
    Named(String),
}

/// Built-in themes in picker order.
const BUILTIN: &[(&str, &str)] = &[
    ("qur_dark", include_str!("../themes/qur_dark.toml")),
    ("qur_light", include_str!("../themes/qur_light.toml")),
    ("one_dark", include_str!("../themes/one_dark.toml")),
    ("one_light", include_str!("../themes/one_light.toml")),
    ("catppuccin_mocha", include_str!("../themes/catppuccin_mocha.toml")),
    ("catppuccin_latte", include_str!("../themes/catppuccin_latte.toml")),
    ("tokyo_night", include_str!("../themes/tokyo_night.toml")),
    ("tokyo_night_day", include_str!("../themes/tokyo_night_day.toml")),
    ("gruvbox_dark", include_str!("../themes/gruvbox_dark.toml")),
    ("gruvbox_light", include_str!("../themes/gruvbox_light.toml")),
    ("nord", include_str!("../themes/nord.toml")),
    ("solarized_dark", include_str!("../themes/solarized_dark.toml")),
    ("solarized_light", include_str!("../themes/solarized_light.toml")),
    ("github_dark", include_str!("../themes/github_dark.toml")),
    ("github_light", include_str!("../themes/github_light.toml")),
    ("high_contrast_dark", include_str!("../themes/high_contrast_dark.toml")),
    ("high_contrast_light", include_str!("../themes/high_contrast_light.toml")),
];

/// The embedded built-in themes, parsed once (first call).
pub struct Registry {
    themes: Vec<Arc<Theme>>,
    qur_dark: Arc<Theme>,
    qur_light: Arc<Theme>,
}

static REGISTRY: OnceLock<Registry> = OnceLock::new();

impl Registry {
    pub fn global() -> &'static Registry {
        REGISTRY.get_or_init(|| Registry::load().unwrap_or_else(|e| panic!("built-in themes: {e}")))
    }

    fn load() -> Result<Registry, String> {
        let parse = |file: &str, src: &str| -> Result<schema::RawTheme, String> {
            toml_edit::de::from_str(src).map_err(|e| format!("{file}.toml: {e}"))
        };
        // Qur Dark and Qur Light are the fallbacks, so they must be complete.
        let qur_dark = Arc::new(build(parse("qur_dark", BUILTIN[0].1)?, None)?);
        let qur_light = Arc::new(build(parse("qur_light", BUILTIN[1].1)?, None)?);
        let mut themes = vec![qur_dark.clone(), qur_light.clone()];
        for (file, src) in &BUILTIN[2..] {
            let raw = parse(file, src)?;
            let bg = raw.ui.window_bg.or(raw.ui.editor_bg).map(|h| h.0);
            let dark = bg.map(|bg| bg.luminance() < 0.18).unwrap_or(raw.appearance.as_deref() != Some("light"));
            let base = if dark { &qur_dark } else { &qur_light };
            themes.push(Arc::new(build(raw, Some(base)).map_err(|e| format!("{file}.toml: {e}"))?));
        }
        Ok(Registry { themes, qur_dark, qur_light })
    }

    /// All themes in picker order (Qur, Popular, Accessibility).
    pub fn all(&self) -> &[Arc<Theme>] {
        &self.themes
    }

    pub fn get(&self, name: &str) -> Option<Arc<Theme>> {
        self.themes.iter().find(|t| t.name.eq_ignore_ascii_case(name)).cloned()
    }

    /// Resolve a choice for the current system appearance.
    /// Unknown names fall back to Auto.
    pub fn resolve(&self, choice: &ThemeChoice, system_dark: bool) -> Arc<Theme> {
        if let ThemeChoice::Named(name) = choice
            && let Some(t) = self.get(name)
        {
            return t;
        }
        if system_dark { self.qur_dark.clone() } else { self.qur_light.clone() }
    }
}

/// Blend `fg` over `bg` (both straight alpha). Used for translucent windows
/// (decision 8) and by the contrast tests.
pub fn blend(fg: Rgba, bg: Rgba) -> Rgba {
    color::blend(fg, bg)
}

/// WCAG 2.x contrast ratio of two opaque colors (1.0 ..= 21.0).
pub fn contrast_ratio(a: Rgba, b: Rgba) -> f32 {
    color::contrast_ratio(a, b)
}

/// CIEDE2000 color difference of two opaque colors.
pub fn delta_e(a: Rgba, b: Rgba) -> f32 {
    color::delta_e(a, b)
}

